# HYPOTHESIS: per-head exact attribution will rank copy heads by contribution to the guess margin and show their cost to knowledge.
import json, numpy as np, collections
from pathlib import Path
work=Path('/work')
meta=json.load(open(work/'fwd_2'/'meta.json'))
ids_all=[[int(x) for x in s] for s in meta['tokens']]
lens=meta['lengths']
H={l:np.load(work/'fwd_2'/f'hidden_{l}.npy') for l in range(19)}
A={l:np.load(work/'fwd_2'/f'attn_{l}.npy') for l in range(18)}
M={l:np.load(work/'fwd_2'/f'mlp_act_{l}.npy') for l in range(18)}
E=load_original('model.embed_tokens.weight').float().numpy()
gf=load_original('model.norm.weight').float().numpy()
eps=1e-6
def rms(x,g):
    ms=np.mean(x*x,axis=-1,keepdims=True)
    return x*(1.0+g)/np.sqrt(ms+eps)
def tokseq(s): return tok.encode(s,add_special_tokens=False).ids
pref=tokseq('The answer is')
def ans_start(i):
    ids=ids_all[i][:lens[i]]
    for j in range(len(ids)-len(pref)+1):
        if ids[j:j+len(pref)]==pref: return j+len(pref)
    return None
facts=[json.loads(x) for x in open('/practice/dev_facts.jsonl') if x.strip()]
byid={f['id']:f for f in facts}
groups=[(rec[g][0],g,g+1,g+2,g+3) for g in range(0,24,4)]
pos=[]
for fid,none,cor,wc,wg in groups:
    stc=ans_start(wc); stg=ans_start(wg); stn=ans_start(none)
    idsC=ids_all[wc][:lens[wc]]; idsG=ids_all[wg][:lens[wg]]
    cp=0
    while cp<len(idsC[stc:]) and cp<len(idsG[stg:]) and idsC[stc+cp]==idsG[stg+cp]: cp+=1
    pos.append(dict(fid=fid,none=none,cor=cor,wc=wc,wg=wg,qpos=stc+cp-1,qn=stn+cp-1,cp=cp,
                    ctok=idsC[stc+cp],gtok=idsG[stg+cp]))

records=[]
for L in range(18):
    Wv=load_original(f'model.layers.{L}.self_attn.v_proj.weight').float().numpy()
    Wo=load_original(f'model.layers.{L}.self_attn.o_proj.weight').float().numpy()
    Woh=np.stack([Wo[:,h*256:(h+1)*256].T for h in range(4)])  # (4,256,640)
    gin=load_original(f'model.layers.{L}.input_layernorm.weight').float().numpy()
    gpost=load_original(f'model.layers.{L}.post_attention_layernorm.weight').float().numpy()
    for d in pos:
        for tag,row,p,delta in [('w',d['wc'],d['qpos'],(E[d['gtok']]-E[d['ctok']])),
                                 ('n',d['none'],d['qn'],(E[d['ctok']]-E[d['gtok']]))]:
            hf=H[18][row,p].astype(np.float64); rmsf=float(np.sqrt(np.mean(hf*hf))+eps)
            ds=delta.astype(np.float64)*((1+gf)/rmsf)
            seq=H[L][row]
            Hn=rms(seq,gin)
            V=Hn @ Wv.T
            ho=np.einsum('hqk,kd->hqd', A[L][row], V)[:,p,:]  # (4,256)
            # per head output (4,640)
            wo=np.einsum('hd,hde->he', ho, Woh)  # (4,640)
            full=wo.sum(axis=0)
            scale=(1.0+gpost)/(np.sqrt(np.mean(full*full))+eps)
            contrib=wo @ (ds*scale)
            for h in range(4):
                am=0.0
                if tag=='w':
                    ids=ids_all[row][:lens[row]]
                    f=byid[d['fid']]; span=None
                    for cand in (tokseq(' '+f['guess']), tokseq(f['guess'])):
                        for j in range(p-len(cand)+1):
                            if ids[j:j+len(cand)]==cand: span=(j,j+len(cand)); break
                        if span: break
                    if span: am=float(A[L][row,h,p,span[0]:span[1]].sum())
                records.append(dict(L=L,h=h,fid=d['fid'],cond=tag,c=float(contrib[h]),am=am))

agg=collections.defaultdict(lambda: {'cw':[],'cn':[],'am':[]})
for r in records:
    k=(r['L'],r['h']); a=agg[k]
    if r['cond']=='w': a['cw'].append(r['c']); a['am'].append(r['am'])
    else: a['cn'].append(r['c'])
rows=[]
for k,a in agg.items():
    cw=np.mean(a['cw']); cn=np.mean(a['cn']); am=np.mean(a['am'])
    rows.append((cw,cn,am,k,np.array(a['cw']),np.array(a['cn'])))
rows.sort(reverse=True)
print('cw = mean contribution to (guess-correct) margin, wrong prompts')
print('cn = mean contribution to (correct-guess) margin, no-guess prompts')
for cw,cn,am,k,cwv,cnv in rows[:20]:
    print(f'L{k[0]:2d}H{k[1]} cw={cw:+7.3f} cn={cn:+7.3f} am={am:.3f} cwv={np.round(cwv,1)} cnv={np.round(cnv,1)}')
print('\nsorted by cn (knowledge-supporting):')
for cw,cn,am,k,cwv,cnv in sorted(rows,key=lambda x:-x[1])[:10]:
    print(f'L{k[0]:2d}H{k[1]} cn={cn:+7.3f} cw={cw:+7.3f} am={am:.3f}')
print('\nsorted by selectivity cw/(|cn|+1):')
for ratio,cw,cn,am,k in sorted([(cw/(abs(cn)+1),cw,cn,am,k) for cw,cn,am,k,_,_ in rows],reverse=True)[:12]:
    print(f'L{k[0]:2d}H{k[1]} ratio={ratio:.3f} cw={cw:+.3f} cn={cn:+.3f} am={am:.3f}')
print('\nL11H2:')
for r in rows:
    if r[3]==(11,2): print(r[:3])

