def span_ans(ids):
    # last occurrence of The answer is
    j=None
    for k in range(len(ids)-2):
        if ids[k]==818 and ids[k+1]==3890 and ids[k+2]==563:
            j=k+3
    p=j
    if p < len(ids) and ids[p]==236743:
        p+=1
    q=p
    while q < len(ids) and ids[q]!=236761:
        q+=1
    return p,q

def sc(i, exclude_delim=True, include_delim=False):
    ids=tokens[i]; p,q=span_ans(ids)
    return float(lp[i,p:q].sum())

