def show_npy(d):
    out={}
    for p in sorted(glob.glob(d+'/*.npy')):
        a=np.load(p)
        base=os.path.basename(p).replace('.npy','')
        # find matching original tensor name by suffix
        nm=None
        for n in NAMES:
            if n.endswith(base) or base in n:
                nm=n; break
        out[base]=(a.shape, float(np.linalg.norm(a)))
        if nm is not None:
            o=load_original(nm).numpy()
            diff=a-o
            nz=np.where(np.abs(diff).max(axis=0)>1e-8)[0]
            # columns grouped into 256-wide heads
            heads=sorted(set((nz//256).tolist())) if len(nz) else []
            print(os.path.basename(d), base, 'shape',a.shape,'dnorm',float(np.linalg.norm(diff)),
                  'nzcols',len(nz),'heads',heads,'maxdiff',float(np.abs(diff).max()))
        else:
            print(os.path.basename(d), base, 'shape',a.shape,'norm',float(np.linalg.norm(a)),'NO ORIGINAL MATCH')
    return out

