def span(ids,L):
    # find start of "The answer is"
    best=None
    for i in range(len(ids)):
        s=tok.decode(ids[i:i+2])
        if s.startswith("The answer"):
            best=i; break
    if best is None:
        for i in range(len(ids)):
            if tok.decode(ids[i:i+1]).startswith("The"):
                best=i; break
    assert best is not None, tok.decode(ids)
    # accumulate until endswith '.'
    acc=""
    for j in range(best,L):
        acc+=tok.decode([ids[j]])
        if acc.rstrip().endswith("."):
            return best,j+1,acc
    return best,L,acc

